    {":", "COLON"},
    {"!", "NOT"},
    {"&&", "AND"},
    {"||", "OR"},
    {"switch","SWITCHTK"},
    {"case", "CASETK"},
};

class Lexer {
    private:
        std::string sourceCode;
        int currentIndex;
        int lineNum;
        int length;
        std::vector<Token> tokens;

    public:
        Lexer(const std::string& code) : sourceCode(code), currentIndex(0), lineNum(1) {
            length = sourceCode.length();
            startLexing();
        }

        void startLexing() {
            while (currentIndex < length) {
                std::string word = getNextWord();
                if (!word.empty()) {
                    addToken(word);
                }
            }
        }

        std::vector<Token> getTokens() const {
            return tokens;
        }

        void addToken(std::string word) {
            if (tokenType.find(word) != tokenType.end()) {
                tokens.emplace_back(word, std::string(word.rbegin(), word.rend()), lineNum);
            } else if (!word.empty() && word.find_first_not_of("0123456789") == std::string::npos) {
                tokens.emplace_back(word, tokenType["IntConst"], lineNum);
            } else if(word.find_first_of('"') == 0 && word.find_last_of('"') == word.length() - 1) {
                tokens.emplace_back(word, tokenType["StringConst"], lineNum);

            } else if (!word.empty() &&
                       ((word[0] >= 'a' && word[0] <= 'z') ||
                        (word[0] >= 'A' && word[0] <= 'Z') || word[0] == '_') &&
                       word.find_first_not_of(
                           "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_") == std::string::npos) {
                tokens.emplace_back(word, tokenType["Ident"], lineNum);
            }
        }

        std::string getNextWord() {
            // Implement the logic to extract the next token from sourceCode
            while (currentIndex < sourceCode.length()) {
                char currentChar = sourceCode[currentIndex];
                if (isspace(currentChar)) {
                    if (currentChar == '\n') {
                        lineNum++;
                    }
                    currentIndex++;
                    continue;
                }
                
                if (isalpha(currentChar)) {
                    std::string word;
                    while (currentIndex < sourceCode.length() && (isalnum(sourceCode[currentIndex]) || sourceCode[currentIndex] == '_')) {
                        word += sourceCode[currentIndex];
                        currentIndex++;
                    }
                    return word;
                }

                if (isdigit(currentChar)) {
                    std::string number;
                    while (currentIndex < sourceCode.length() && isdigit(sourceCode[currentIndex])) {
                        number += sourceCode[currentIndex];
                        currentIndex++;
                    }
                    return number;
                }
               
                if (currentChar == '"') {
                    std::string strConst;
                    strConst += currentChar; // Add the opening quote
                    currentIndex++;
                    while (currentIndex < sourceCode.length() && sourceCode[currentIndex] != '"') {
                        strConst += sourceCode[currentIndex];
                        currentIndex++;
                    }
                    if (currentIndex < sourceCode.length()) {
                        strConst += sourceCode[currentIndex]; // Add the closing quote
                        currentIndex++;
                    }
                    return strConst;
                }

                if (ispunct(currentChar)) {
                    std::string punct(1, currentChar);
                    currentIndex++;
                    // Check for multi-character operators (e.g., !=, ==, >=, <=, &&, ||)
                    if (currentIndex < sourceCode.length()) {
                        std::string twoCharOp = punct + sourceCode[currentIndex];
                        if (tokenType.find(twoCharOp) != tokenType.end()) {
                            currentIndex++;
                            return twoCharOp;
                        }
                    }
                    return punct;
                }

                if (currentChar == '\'') {
                    std::string charConst;
                    charConst += currentChar; 
                    currentIndex++;
                    if (currentIndex < sourceCode.length()) {
                        charConst += sourceCode[currentIndex]; 
                        currentIndex++;
                    }
                    if (currentIndex < sourceCode.length() && sourceCode[currentIndex] == '\'') {
                        charConst += sourceCode[currentIndex]; 
                        currentIndex++;
                    }
                    return charConst;
                }

            }
            // Update currentIndex and lineNum accordingly
            // Return a Token object with the extracted word, reverseWord, and lineNum
        }
};
