#undef X
  };

  auto index = static_cast<size_t>(type);
  if (index < static_cast<size_t>(TokenType::EOFTK)) {
    os << token_type_names[index];
  }
  return os;
}
}  // namespace frontend::token

namespace frontend::tokenMatch {
using token::RESERVED_WORDS, token::DELIMITERS;

auto try_match_reserved(std::string_view text) -> MatchResult {
  if (text.empty() || !isalpha(text[0])) return std::nullopt;

  for (const auto& [word, token] : RESERVED_WORDS) {
    auto word_len = word.size();
    if (word_len <= text.size() && text.substr(0, word_len) == word) {
      if (word_len == text.size() ||
          (word_len < text.size() && text[word_len] != '_' &&
           !isalnum(text[word_len]))) {
        return std::make_pair(word_len, token);
      }
    }
  }
  return std::nullopt;
}

auto try_match_identifier(std::string_view text) -> MatchResult {
  if (text.empty() || (!isalpha(text[0]) && text[0] != '_'))
    return std::nullopt;

  size_t len = 1;
  while (len < text.size() && (isalnum(text[len]) || text[len] == '_')) len++;

  return std::make_pair(len, TokenType::IDENFR);
}

auto try_match_str_const(std::string_view text) -> MatchResult {
  if (text.empty() || text[0] != '\"') return std::nullopt;

  size_t len = 1;
  while (len < text.size() && text[len] != '\"') len++;

  ENSURE(len < text.size() && text[len] == '\"',
         "Missing closing quote for string constant");

  return std::make_pair(len + 1, TokenType::STRCON);
}

auto try_match_int_const(std::string_view text) -> MatchResult {
  if (text.empty() || !isdigit(text[0])) return std::nullopt;

  // TODO: error when number not ending with white space. e.g. 123abc
  size_t len = 1;
  if (text[0] != '0') {
    while (len < text.size() && isdigit(text[len])) len++;
  }

  return std::make_pair(len, TokenType::INTCON);
}

auto try_match_delimiter(std::string_view text) -> MatchResult {
  if (text.empty() || isalnum(text[0])) return std::nullopt;

  for (const auto& [delimiter, token] : DELIMITERS) {
    auto len = delimiter.size();
    if (len <= text.size() && text.substr(0, len) == delimiter) {
      return std::make_pair(len, token);
    }
  }

  // error handling for & and |
  if (text[0] == '&') {
    return {std::make_pair(1, TokenType::AND), true};
  } else if (text[0] == '|') {
    return {std::make_pair(1, TokenType::OR), true};
  }

  return std::nullopt;
}

}  // namespace frontend::tokenMatch
--- REFERENCE LEXER ---
#include "lexer.hpp"

#include <cctype>
#include <cstddef>
#include <ostream>
#include <stdexcept>
#include <string>
#include <utility>

#include "error.hpp"
#include "token.hpp"

namespace frontend::lexer {
using tokenMatch::try_match;

bool Lexer::next() {
  if (!token_lists.empty() && token_lists.back().is_EOF()) return false;

  while (skip_whitespace() || skip_comment());
  if (cur_loc.empty()) {
    token_lists.emplace_back(TokenType::EOFTK, "", cur_line + 1);
    return false;
  }

  if (auto result = try_match(cur_loc); result.has_value()) {
    if (result.has_error()) {
      // the only error in lexer
      report_error(ErrorType::LEX_INVALID_TOKEN, cur_line);
    }

    const auto& [len, type] = result.value();
    auto token = Token(type, std::string(cur_loc.substr(0, len)), cur_line);
    cur_loc.remove_prefix(len);
    token_lists.emplace_back(std::move(token));
    return true;
  }

  throw std::runtime_error("unreachable code in Lexer::next");
}

auto Lexer::peek(std::ptrdiff_t offset) -> const Token& {
  const auto position = static_cast<std::ptrdiff_t>(cur_idx) + offset;
  ENSURE(position >= 0, "cannot look before the start of the token stream");
  const auto target = static_cast<size_t>(position);

  while (target >= token_lists.size()) {
    if (!next()) {
      // next() returned false, meaning EOF was reached and added.
      ENSURE(!token_lists.empty() && token_lists.back().is_EOF(),
             "Expected EOF token");
      return token_lists.back();
    }
  }

  return token_lists[target];
}

void Lexer::advance() {
  if (peek(0).is_EOF()) return;
  cur_idx++;
}

void Lexer::output_tokens(std::ostream& os) {
  while (next());  // ensure all tokens are generated

  for (const auto& token : token_lists) {
    os << token << '\n';
  }
}

void Lexer::branch() { branch_stack.push(cur_idx); }
void Lexer::commit() {
  ENSURE(!branch_stack.empty(), "commit called without a corresponding branch");
  branch_stack.pop();
}
void Lexer::rollback() {
  ENSURE(!branch_stack.empty(),
         "rollback called without a corresponding branch");
  cur_idx = branch_stack.top();
  branch_stack.pop();
}

// skip ' ' \t \n \r \v \f
bool Lexer::skip_whitespace() {
  bool skipped = false;
  while (!cur_loc.empty() && isspace(cur_loc[0])) {
    if (cur_loc[0] == '\n') cur_line++;

    cur_loc.remove_prefix(1);
    skipped = true;
  }

  return skipped;
}

bool Lexer::skip_comment() {
  if (cur_loc.size() < 2 || cur_loc[0] != '/') return false;

  bool skipped = false;
  if (cur_loc[1] == '/') {
    size_t len = 2;
    while (len < cur_loc.size() && cur_loc[len] != '\n') len++;

    if (len < cur_loc.size()) {
      len++;
      cur_line++;
    }
    cur_loc.remove_prefix(len);
    skipped = true;
  } else if (cur_loc[1] == '*') {
    size_t len = 2;

    // TODO: error when not ending with */
    while (len < cur_loc.size() - 1) {
      if (cur_loc[len] == '\n') cur_line++;

      if (cur_loc[len] == '*' && cur_loc[len + 1] == '/') {
        len += 2;
        break;
      }
      len++;
    }

    cur_loc.remove_prefix(len);
    skipped = true;
  }

  return skipped;
}

}  // namespace frontend::lexer

