 230:                         currentIndex += 2; // Skip the "//"
 231:                         while (currentIndex < sourceCode.length() && sourceCode[currentIndex] != '\n') {
 232:                             currentIndex++;
 233:                         }
 234:                         continue; // Skip to the next iteration
 235:                     } else if (currentIndex + 1 < sourceCode.length() && sourceCode[currentIndex + 1] == '*') {
