 255:                     if (currentIndex < sourceCode.length()) {
 256:                         charConst += sourceCode[currentIndex]; 
 257:                         currentIndex++;
 258:                     }
 259:                     if (currentIndex < sourceCode.length() && sourceCode[currentIndex] == '\'') {
 260:                         charConst += sourceCode[currentIndex]; 
 261:                         currentIndex++;
 262:                     }
 263:                     return charConst;
 264:                 }
