   5:     public:
   6:         Token(std::string _word,std::string _tokenType,int _lineNum):
   7:             word(_word), tokenType(_tokenType), lineNum(_lineNum){}
   8: 
   9:         std::string getWord() const {
  10:             return word;
  11:         }
