  22:     private:
  23:         std::string word;
  24:         std::string tokenType;
  25:         int lineNum;
  26: };
--- .\code\src\front-end\Lexer.cpp ---
   1: #include <unordered_map>
   2: #include <string>
   3: #include "token.hpp"
   4: #include <vector>
   5: #include "compileError.hpp"
   6: 
   7: std::unordered_map<std::string, std::string> tokenType = {
   8:     {"Ident", "IDENFR"},
   9:     {"IntConst","INTCON"},
  10:     {"CharConst","CHARCON"},
  11:     {"StringConst","STRCON"},
  12:     {"continue","CONTINUETK"},
  13:     {"default","DEFAULTTK"},
  14:     {"printf","PRINTFTK"},
  15:     {"return","RETURNTK"},
  16:     {"void","VOIDTK"},
  17:     {"break","BREAKTK"},
  18:     {"else","ELSETK"},
  19:     {"if","IFTK"},
  20:     {"int","INTTK"},
  21:     {"main","MAINTK"},
  22:     {"switch","SWITCHTK"},
  23:     {"while","WHILETK"},
  24:     {"const","CONSTTK"},
  25:     {"char","CHARTK"},
  26:     {"void","VOIDTK"},
  27:     {"const","CONSTTK"},
  28:     {"!=","NEQ"},
  29:     {"==","EQL"},
  30:     {">=","GEQ"},
  31:     {"<=","LEQ"},
  32:     {">", "GRE"},
  33:     {"<", "LSS"},
  34:     {"+", "PLUS"},
  35:     {"-", "MINU"},
  36:     {"*", "MULT"},
  37:     {"/", "DIV"},
  38:     {"%", "MOD"},
  39:     {"=", "ASSIGN"},
  40:     {";", "SEMICN"},
  41:     {",", "COMMA"},
  42:     {"(", "LPARENT"},
  43:     {")", "RPARENT"},
  44:     {"[", "LBRACK"},
  45:     {"]", "RBRACK"},
  46:     {"{", "LBRACE"},
  47:     {"}", "RBRACE"},
  48:     {":", "COLON"},
  49:     {"!", "NOT"},
  50:     {"&&", "AND"},
  51:     {"||", "OR"},
  52:     {"switch","SWITCHTK"},
  53:     {"case", "CASETK"},
  54:     {"static","STATICTK"},
  55: };
  56: 
  57: class Lexer {
  58:     private:
  59:         std::string sourceCode;
  60:         int currentIndex = 0;
  61:         int lineNum = 1;
  62:         int length;
  63:         std::vector<Token> tokens;
  64:         std::vector<compileError> errors;
  65: 
  66:     public:
  67:         Lexer(const std::string& code) : sourceCode(code), currentIndex(0), lineNum(1) {
  68:             length = sourceCode.length();
  69:             startLexing();
  70:         }
  71: 
  72:         void startLexing() {
  73:             while (currentIndex < length) {
  74:                 std::string word = getNextWord();
  75:                 if (!word.empty()) {
  76:                     addToken(word,lineNum);
  77:                 }
  78:             }
  79:         }
  80: 
  81:         std::vector<Token> getTokens() const {
  82:             return tokens;
  83:         }
  84: 
  85:         void addToken(const std::string& word, int tokenLine) {
  86:         auto it = tokenType.find(word);
  87: 
  88:     // 关键字、运算符、分隔符
  89:         if (it != tokenType.end()) {
  90:            tokens.emplace_back(word, it->second, tokenLine);
  91:            return;
  92:        }
  93: 
  94:     // 整数
  95:        if (!word.empty() &&
  96:           word.find_first_not_of("0123456789") == std::string::npos) {
  97:           tokens.emplace_back(
  98:               word,
  99:               tokenType.at("IntConst"),
 100:                tokenLine
 101:           );
 102:           return;
 103:         }
 104: 
 105:     // 字符串
 106:     if (word.size() >= 2 &&
 107:         word.front() == '"' &&
 108:         word.back() == '"') {
 109: 
 110:         tokens.emplace_back(
 111:             word,
 112:             tokenType.at("StringConst"),
 113:             tokenLine
 114:         );
 115:         return;
 116:     }
 117: 
 118:     // 字符常量
 119:     if (word.size() >= 3 &&
 120:         word.front() == '\'' &&
 121:         word.back() == '\'') {
 122: 
 123:         tokens.emplace_back(
 124:             word,
 125:             tokenType.at("CharConst"),
 126:             tokenLine
 127:         );
 128:         return;
 129:     }
 130: 
 131:     // 标识符
 132:     if (!word.empty() &&
 133:         (std::isalpha(static_cast<unsigned char>(word[0]))
 134:          || word[0] == '_')) {
 135: 
 136:         bool valid = true;
 137: 
 138:         for (char c : word) {
 139:             if (!std::isalnum(static_cast<unsigned char>(c))
 140:                 && c != '_') {
 141:                 valid = false;
 142:                 break;
 143:             }
 144:         }
 145: 
 146:         if (valid) {
 147:             tokens.emplace_back(
 148:                 word,
 149:                 tokenType.at("Ident"),
 150:                 tokenLine
 151:             );
 152:             return;
 153:         }
 154:     }
 155: }
 156: 
 157:         std::string getNextWord() {
 158:             while (currentIndex < sourceCode.length()) {
 159:                 char currentChar = sourceCode[currentIndex];
 160:                 if (isspace(currentChar)) {
 161:                     if (currentChar == '\n') {
 162:                         lineNum++;
 163:                     }
 164:                     currentIndex++;
 165:                     continue;
 166:                 }
 167:                 if (currentChar == '&') {
 168:                     if (currentIndex + 1 < length &&
 169:                         sourceCode[currentIndex + 1] == '&') {
 170: 
 171:                         currentIndex += 2;
 172:                         return "&&";
 173:                         }
 174:                     errors.push_back(compileError(lineNum,'a'));
 175:                     currentIndex++;
 176:                     return "&";
 177:                 }
 178:                 if (currentChar == '|') {
 179:                     if (currentIndex + 1 < length &&
 180:                         sourceCode[currentIndex + 1] == '|') {
 181: 
 182:                         currentIndex += 2;
 183:                         return "||";
 184:                         }
 185:                     errors.push_back(compileError(lineNum,'a'));
 186:                     currentIndex++;
 187:                     return "|";
 188:                 }
 189: 
 190:                 if (isalpha(currentChar) || currentChar == '_') {
 191:                     std::string word;
 192:                     while (currentIndex < sourceCode.length() && (isalnum(sourceCode[currentIndex]) || sourceCode[currentIndex] == '_')) {
 193:                         word += sourceCode[currentIndex];
 194:                         currentIndex++;
 195:                     }
 196:                     return word;
 197:                 }
 198: 
 199:                 if (isdigit(currentChar)) {
 200:                     std::string number;
 201:                     if (currentChar == '0') {
 202:                         currentIndex++;
 203:                         return "0";
 204:                     }
 205:                     while (currentIndex < sourceCode.length() && isdigit(sourceCode[currentIndex])) {
 206:                         number += sourceCode[currentIndex];
 207:                         currentIndex++;
 208:                     }
