class Lexer {
    private:
        std::string sourceCode;
        int currentIndex = 0;
        int lineNum = 1;
        int length;
        std::vector<Token> tokens;
        std::vector<compileError> errors;

    public:
        Lexer(const std::string& code) : sourceCode(code), currentIndex(0), lineNum(1) {
            length = sourceCode.length();
            startLexing();
        }

        void startLexing() {
            while (currentIndex < length) {
                std::string word = getNextWord();
                if (!word.empty()) {
                    addToken(word,lineNum);
                }
            }
        }

        std::vector<compileError> getErrors() {
            return errors;
        }

        std::vector<Token> getTokens() const {
            return tokens;
        }

        void addToken(const std::string& word, int tokenLine) {
        auto it = tokenType.find(word);

    // 关键字、运算符、分隔符
        if (it != tokenType.end()) {
           tokens.emplace_back(word, it->second, tokenLine);
           return;
       }

